    /// Authenticate with email/password and enable generation-fenced automatic refresh.
    pub async fn with_credentials(
        api_key: impl Into<String>,
        email: impl Into<String>,
        password: impl Into<String>,
    ) -> Result<Self> {
        let client = Self::builder().publishable_key(api_key).build()?;
        let tokens = client
            .auth()
            .post_api_v1_auth_login(&PostApiV1AuthLoginInput {
                email: email.into(),
                password: password.into(),
            })
            .await?;
        client
            .install_session(
                tokens.token.clone(),
                Some(tokens.refresh_token.clone()),
                "/api/v1/auth/refresh",
            )
            .await;
        Ok(client)
    }
